using UnityEngine;
namespace Blocklands {public partial class Sandbox {
  Transform forestFriend,friendVehicle,friendGift;LineRenderer handLink;Material handMaterial;
  Vector3 tripStart,tripTarget,departureStart;float tripAt,giftAt;int friendStage,friendRegion,giftRegion;bool giftComing,giftWaiting;
  public bool ForestFriendFollowing=>friendStage==3;
  public bool ForestFriendWaiting=>friendStage==2;
  public bool ForestFriendArriving=>friendStage==1;
  public bool FriendGiftWaiting=>giftWaiting;
  public bool FriendGiftComing=>giftComing;
  public int ForestFriendArrivalSeconds=>friendStage==1?Mathf.Max(0,Mathf.CeilToInt(8f-(Time.time-tripAt))):0;
  public string ForestFriendStatusText=>friendStage==1?"小禾正在乘空中小汽车赶来，约"+ForestFriendArrivalSeconds+"秒后到"+VisitorGateName():friendStage==2?World.Region==0?"小禾就在小屋旁，靠近按G牵手":"小禾已经到"+VisitorGateName()+"，靠近按G迎接":friendStage==3?"小禾已经在你身边，正牵手同行":friendStage==4?"小禾正乘车回森林小屋":World!=null&&World.Region==0?"小禾就在林地小屋；按G聊天，电话邀请后按G牵手":"小禾还没出发；打电话邀请她来玩吧";
  public Vector3 ForestFriendPosition=>forestFriend!=null?forestFriend.position:Vector3.zero;
  Vector3 FriendFollowGoal()=>PartyFollowOrigin+Player.transform.forward*1.05f-Player.transform.right*.72f;
  void FaceFriendTowardPlayer(){Vector3 look=Player.transform.position-forestFriend.position;look.y=0;if(look.sqrMagnitude>.05f)forestFriend.rotation=Quaternion.LookRotation(look);}
  public Vector3 FriendGiftPosition=>friendGift!=null?friendGift.position:Vector3.zero;
  Vector3 VisitorGate(){if(World.Region==6)return new Vector3(31.5f,16,10);if(World.Region==1)return new Vector3(31.5f,15,10);if(World.Region==0)return new Vector3(37,19,32);Vector3 p=World.SafeSpawn();int x=Mathf.FloorToInt(p.x),z=Mathf.FloorToInt(p.z);for(int y=Mathf.FloorToInt(p.y);y>VoxelWorld.MinY;y--)if(Blocks.Solid(World.Get(new Vector3Int(x,y,z))))return new Vector3(p.x,y+1.1f,p.z);return p;}
  Vector3 ForestHomeSpot()=>new Vector3(28.5f,19.1f,37.5f);
  string VisitorGateName()=>World.Region==6?"城堡一层大门":World.Region==1?"村庄入口":World.Region==0?"森林小屋门口":VoxelWorld.RegionNames[World.Region]+"入口";
  void MakeForestFriend(){if(forestFriend!=null)return;var a=RoyalArt.ForestFriend(transform);forestFriend=a.transform;NpcNavigation.Ensure(forestFriend);forestFriend.gameObject.SetActive(false);var o=new GameObject("牵手姿态（不绘制连线）");o.transform.SetParent(transform,false);handLink=o.AddComponent<LineRenderer>();handLink.enabled=false;}
  void RefreshForestFriendPresence(){MakeForestFriend();handLink.gameObject.SetActive(true);if(friendStage==0){forestFriend.SetParent(transform,true);forestFriend.position=ForestHomeSpot();forestFriend.rotation=Quaternion.Euler(0,180,0);forestFriend.gameObject.SetActive(World.Region==0);handLink.enabled=false;}}
  Transform MakeFlyingCart(Vector3 pos){var root=new GameObject("小禾的空中小汽车").transform;root.SetParent(transform);root.position=pos;var a=root.gameObject.AddComponent<RoyalArt>();Color pink=new Color(.95f,.52f,.73f),white=new Color(.9f,.94f,1);a.Piece("车身",new Vector3(0,.45f,0),new Vector3(2.4f,.8f,3),pink);a.Piece("敞篷驾驶位",new Vector3(0,1.05f,-.2f),new Vector3(1.7f,.5f,1.1f),white);foreach(float side in new[]{-1f,1f}){a.Piece("小飞机翅膀",new Vector3(side*1.7f,.3f,0),new Vector3(1.8f,.12f,1.2f),white);for(float z=-.8f;z<=.9f;z+=1.7f)a.Piece("小车轮",new Vector3(side*1.15f,.08f,z),new Vector3(.4f,.4f,.2f),new Color(.25f,.23f,.4f),PrimitiveType.Cylinder);}a.Piece("前灯",new Vector3(0,.6f,1.52f),Vector3.one*.25f,Color.yellow,PrimitiveType.Sphere);return root;}
  public void InviteForestFriend(){MakeForestFriend();if(friendStage==1||friendStage==2||friendStage==3){Notice=ForestFriendStatusText;return;}if(World.Region==0){friendStage=2;friendRegion=0;forestFriend.SetParent(transform,true);if(friendVehicle!=null)Destroy(friendVehicle.gameObject);friendVehicle=null;forestFriend.position=ForestHomeSpot();forestFriend.rotation=Quaternion.Euler(0,180,0);forestFriend.gameObject.SetActive(true);Notice="小禾：我就在小屋呀！走近按G，我们一起牵手出去玩。";return;}friendStage=1;friendRegion=World.Region;tripAt=Time.time;tripTarget=VisitorGate();tripStart=tripTarget+new Vector3(-17,20,-20);if(friendVehicle!=null)Destroy(friendVehicle.gameObject);friendVehicle=MakeFlyingCart(tripStart);forestFriend.SetParent(friendVehicle,true);forestFriend.localPosition=new Vector3(0,1.15f,-.3f);forestFriend.gameObject.SetActive(true);Notice="小禾驾驶空中小汽车出发了，约8秒后到"+VisitorGateName()+"。";}
  public void RequestFriendGift(){giftComing=true;giftWaiting=false;giftAt=Time.time;giftRegion=World.Region;if(friendGift!=null)Destroy(friendGift.gameObject);friendGift=new GameObject("寄来的粉色礼物盒").transform;friendGift.SetParent(transform);friendGift.position=VisitorGate()+Vector3.up*13;var a=friendGift.gameObject.AddComponent<RoyalArt>();a.Piece("粉色礼物盒",Vector3.zero,new Vector3(.85f,.85f,.85f),new Color(.96f,.53f,.75f));a.Piece("礼物金色蝴蝶结",Vector3.up*.49f,new Vector3(.95f,.12f,.15f),new Color(1,.83f,.38f));Notice="礼物正在送来，稍后去"+VisitorGateName()+"领。";}
  public bool TryMeetFriendOrGift(){if(Paused)return false;Vector3 p=Player.transform.position;if(friendStage==2&&Vector3.Distance(p,forestFriend.position)<3){friendStage=3;forestFriend.position=FriendFollowGoal();FaceFriendTowardPlayer();handLink.enabled=false;Notice="小禾在你左前方牵住你的手，现在能看见她了。按 X 送她回森林小屋；按C可看见两人牵手。";EarnActivityCoins(16,"迎接小禾");return true;}if(friendStage==0&&World.Region==0&&forestFriend!=null&&Vector3.Distance(p,forestFriend.position)<3){Notice="小禾：我就在小屋里。想一起旅行就打电话说‘和我一起玩’，然后按G牵手。";return true;}if(giftWaiting&&friendGift!=null&&Vector3.Distance(p,friendGift.position)<2.7f){giftWaiting=false;friendGift.gameObject.SetActive(false);Inventory[(int)Block.Cookie]=Mathf.Min(9999,Inventory[(int)Block.Cookie]+2);EarnActivityCoins(18,"领取礼物");Notice="小禾送来两块饼干，还有18元。";return true;}return false;}
  public bool SendForestFriendHome(){if(friendStage==0||Paused)return false;MakeForestFriend();handLink.enabled=false;if(World.Region==0){friendStage=0;RefreshForestFriendPresence();Notice="小禾已经在森林小屋里休息，不用再坐车回来。";return true;}friendStage=4;tripAt=Time.time;departureStart=forestFriend.position;tripTarget=departureStart+new Vector3(16,20,-18);forestFriend.SetParent(transform,true);if(friendVehicle!=null)Destroy(friendVehicle.gameObject);friendVehicle=MakeFlyingCart(departureStart);forestFriend.SetParent(friendVehicle,true);forestFriend.localPosition=new Vector3(0,1.15f,-.3f);Notice="小禾坐上空中小汽车，回森林小屋了。";return true;}
  void RestoreForestFriend(SavedWorld save){if(forestFriend!=null){forestFriend.SetParent(transform,true);forestFriend.gameObject.SetActive(false);}if(friendVehicle!=null)Destroy(friendVehicle.gameObject);friendVehicle=null;handLink?.gameObject.SetActive(false);friendStage=0;giftComing=giftWaiting=false;if(friendGift!=null){Destroy(friendGift.gameObject);friendGift=null;}
   if(save.friendFollowing||save.friendWaiting){MakeForestFriend();forestFriend.gameObject.SetActive(true);friendRegion=World.Region;friendStage=save.friendFollowing?3:2;forestFriend.position=save.friendFollowing?FriendFollowGoal():VisitorGate();if(save.friendFollowing)FaceFriendTowardPlayer();handLink.gameObject.SetActive(true);handLink.enabled=false;}
   if(save.friendGiftWaiting){RequestFriendGift();giftComing=false;giftWaiting=true;friendGift.position=VisitorGate()+Vector3.right*2;}RefreshForestFriendPresence();
  }
  void TickForestFriend(){if(Player==null||Paused)return;if(friendStage!=0&&friendRegion!=World.Region){friendRegion=World.Region;if(friendStage==3){forestFriend.SetParent(transform,true);forestFriend.position=FriendFollowGoal();FaceFriendTowardPlayer();}
    else if(friendStage==1){tripAt=Time.time;tripTarget=VisitorGate();tripStart=tripTarget+new Vector3(-17,20,-20);Notice="小禾改到"+VisitorGateName()+"找你，约8秒后到。";}
    else if(friendStage==2){forestFriend.position=VisitorGate();Notice="小禾已经到"+VisitorGateName()+"，去迎接她吧。";}
    else {friendStage=0;handLink.enabled=false;if(forestFriend!=null)forestFriend.gameObject.SetActive(false);if(friendVehicle!=null)Destroy(friendVehicle.gameObject);friendVehicle=null;}}
   if(friendStage==1){float t=Mathf.SmoothStep(0,1,Mathf.Clamp01((Time.time-tripAt)/8));friendVehicle.position=Vector3.Lerp(tripStart,tripTarget,t)+Vector3.up*Mathf.Sin(t*Mathf.PI)*2;if(t>=1){forestFriend.SetParent(transform,true);forestFriend.position=tripTarget;if(friendVehicle!=null)Destroy(friendVehicle.gameObject);friendVehicle=null;friendStage=2;Notice="小禾到了！去"+VisitorGateName()+"接她，靠近按 G。";}}
   if(friendStage==3){Vector3 goal=FriendFollowGoal();Quaternion facing=Player.transform.rotation;if(PartyPlayingBall)goal=CastleBallPlay.Court+Vector3.left*2.5f;if(CoasterRiding)ActiveCoaster.PartySeat(0,out goal,out facing);if(CoasterRiding)forestFriend.position=goal;else NpcNavigation.Ensure(forestFriend).MoveTo(goal,10,Time.deltaTime);forestFriend.rotation=CoasterRiding?facing:Quaternion.Slerp(forestFriend.rotation,facing,Time.deltaTime*8);handLink.enabled=false;}
   if(friendStage==4){float t=Mathf.Clamp01((Time.time-tripAt)/4);friendVehicle.position=Vector3.Lerp(departureStart,tripTarget,t);if(t>=1){friendStage=0;forestFriend.SetParent(transform,true);Destroy(friendVehicle.gameObject);friendVehicle=null;RefreshForestFriendPresence();}}
   if(friendGift!=null&&giftComing){if(giftRegion!=World.Region){giftRegion=World.Region;giftAt=Time.time;friendGift.position=VisitorGate()+Vector3.up*13;}float t=Mathf.Clamp01((Time.time-giftAt)/5);friendGift.position=Vector3.Lerp(VisitorGate()+Vector3.up*13,VisitorGate()+Vector3.right*2,t);if(t>=1){giftComing=false;giftWaiting=true;Notice="礼物到了"+VisitorGateName()+"！靠近粉色礼物盒按 G。";}}
  }
  void DrawForestFriend(float w,float h){bool homeNearby=friendStage==0&&World.Region==0&&forestFriend!=null&&Vector3.Distance(Player.transform.position,forestFriend.position)<6;if(Paused||(!giftWaiting&&!homeNearby&&friendStage!=1&&friendStage!=2&&friendStage!=3))return;string s=giftWaiting?"粉色礼物到了：去"+VisitorGateName()+"按 G 领取":homeNearby?"小禾就在眼前 · G聊天 · 电话邀请后再按G牵手":friendStage==3?"小禾就在你左前方牵手同行 · X送她回小屋":ForestFriendStatusText;Panel(new Rect(w/2-300,130,600,38),new Color(.28f,.13f,.27f,.9f));Label(new Rect(w/2-290,136,580,29),s,16,Color.white,TextAnchor.MiddleCenter);}
  void DisposeForestFriend(){if(handMaterial!=null){Destroy(handMaterial);handMaterial=null;}}
}}
